/// `orient2d`'s exact value in plain `i128` (chapter 23.3): each step in `i128`, or in its
/// certificate's wide type with both operands widened to it, with checked arithmetic; `None` only
/// if a step overflowed, which the certificate rules out.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    reason = "each name is a step of the description, named by the language's rule"
)]
pub fn orient2d_value(a: P2, b: P2, c: P2) -> Option<i128> {
    let ba_x = i128::from(b.x.get()).checked_sub(i128::from(a.x.get()))?;
    let ba_y = i128::from(b.y.get()).checked_sub(i128::from(a.y.get()))?;
    let ca_x = i128::from(c.x.get()).checked_sub(i128::from(a.x.get()))?;
    let ca_y = i128::from(c.y.get()).checked_sub(i128::from(a.y.get()))?;
    let det_1 = ba_x.checked_mul(ca_y)?;
    let det_2 = ba_y.checked_mul(ca_x)?;
    let det = det_1.checked_sub(det_2)?;
    Some(det)
}

/// `orient3d`'s exact value in plain `i128` (chapter 23.3): each step in `i128`, or in its
